#### 4.2.2 Implementation Pattern

1. **Service Definition** (STD-APP-API-002)

```javascript
// User Service - Internal API
class UserService {
    constructor(config) {
        this.app = express();
        this.setupMiddleware();
        this.setupRoutes();
    }

    setupMiddleware() {
        // Internal service authentication
        this.app.use(
            auth.serviceToService({
                trustedServices: ['profile-service', 'order-service'],
                clientCertificates: true,
            })
        );

        // Service mesh headers
        this.app.use((req, res, next) => {
            res.set({
                'X-Service-Name': 'user-service',
                'X-Service-Version': '1.2.3',
            });
            next();
        });
    }

    setupRoutes() {
        // Internal API - simplified interface
        this.app.get('/internal/v1/users/:userId', this.getUser);
        this.app.post('/internal/v1/users', this.createUser);
    }

    async getUser(req, res) {
        const userId = req.params.userId;
        const requestingService = req.headers['x-service-name'];

        // Internal services can access more data
        const user = await this.userRepository.findById(userId);

        // Return different data based on requesting service
        if (requestingService === 'profile-service') {
            res.json(user); // Full user object
        } else {
            res.json({
                // Minimal user object for other services
                id: user.id,
                email: user.email,
                status: user.status,
            });
        }
    }
}
```

2. **Service Communication** (STD-APP-API-004 East-West)

```javascript
// Profile Service calling User Service
class ProfileService {
    constructor() {
        this.userServiceClient = new ServiceClient({
            serviceName: 'user-service',
            baseUrl: 'http://user-service:8080',
            timeout: 5000,
            retries: 3,
        });
    }

    async getProfile(userId) {
        try {
            // East-West communication with circuit breaker
            const user = await this.userServiceClient.get(`/internal/v1/users/${userId}`, {
                headers: {
                    'X-Service-Name': 'profile-service',
                    'X-Request-ID': generateRequestId(),
                },
            });

            return this.enrichProfile(user);
        } catch (error) {
            // Graceful degradation
            if (error.status === 503) {
                return this.getCachedProfile(userId);
            }
            throw error;
        }
    }
}
