                audience: 'partner-api',
                optional: false,
            }),

            // 3. Rate limiting per partner
            rateLimit.perPartner({
                windowMs: 60000,
                max: (req) => req.partner.rateLimit || 100,
            }),
        ]);
    }

    setupRoutes() {
        // Partner-specific endpoints
        this.app.post('/partner/v1/claims', this.processPartnerClaim);
        this.app.get('/partner/v1/reports/:reportId', this.getPartnerReport);
    }

    async processPartnerClaim(req, res) {
