        const claim = req.body;

        // Partner-specific validation rules
        const validator = await this.getPartnerValidator(partnerId);
        const validationResult = await validator.validate(claim);

        if (!validationResult.isValid) {
            return res.status(400).json({
                error: 'validation_failed',
                details: validationResult.errors,
            });
        }

        const result = await this.claimProcessor.process(claim, {
            partnerId,
            source: 'partner_api',
        });

        res.status(201).json(result);
    }
}
