#### 4.4.2 Mobile-Optimized Implementation

```javascript
// Mobile-optimized API patterns
class MobileAPI {
    constructor() {
        this.app = express();
        this.setupMobileOptimizations();
        this.setupRoutes();
    }

    setupMobileOptimizations() {
        // Mobile-specific middleware
        this.app.use('/mobile/v1', [
            // Detect mobile client
            (req, res, next) => {
                req.isMobile = /mobile|android|ios/i.test(req.headers['user-agent']);
                next();
            },

            // Conditional field selection for mobile
            this.fieldSelection,

            // Response compression
            compression(),

            // Cache optimization for mobile
            this.mobileCache,
        ]);
    }

    fieldSelection(req, res, next) {
        // Allow mobile clients to specify fields
        if (req.query.fields) {
            req.selectedFields = req.query.fields.split(',');
        } else if (req.isMobile) {
            // Default mobile field set (smaller payload)
            req.selectedFields = ['id', 'name', 'status', 'updatedAt'];
        }
        next();
    }

    async getUserProfile(req, res) {
        const userId = req.params.userId;
        const profile = await this.userService.getProfile(userId);

        // Return filtered data for mobile
        if (req.selectedFields) {
            const filteredProfile = {};
            req.selectedFields.forEach((field) => {
                if (profile[field] !== undefined) {
                    filteredProfile[field] = profile[field];
                }
            });
            return res.json(filteredProfile);
        }

        res.json(profile);
    }

    // Mobile-friendly pagination
    async searchUsers(req, res) {
        const {
            query,
            page = 1,
            limit = req.isMobile ? 10 : 25, // Smaller pages for mobile
        } = req.query;

        const results = await this.userService.search({
            query,
            page: parseInt(page),
            limit: parseInt(limit),
        });

        // Mobile-friendly response structure
        res.json({
            data: results.users,
            pagination: {
                page: results.page,
                totalPages: results.totalPages,
                hasMore: results.page < results.totalPages,
            },
        });
    }
}
