// Legacy system API wrapper
class LegacySystemAPI {
    constructor(legacyConfig) {
        this.app = express();
        this.legacyClient = new LegacySOAPClient(legacyConfig);
        this.setupRoutes();
    }

    setupRoutes() {
        // Modern REST endpoints that wrap legacy SOAP calls
        this.app.get('/api/v1/customers/:customerId', this.getCustomer);
        this.app.post('/api/v1/customers', this.createCustomer);
        this.app.put('/api/v1/customers/:customerId', this.updateCustomer);
    }

    async getCustomer(req, res) {
        try {
            const customerId = req.params.customerId;

            // Call legacy SOAP service
            const soapResponse = await this.legacyClient.call('GetCustomer', {
                CustomerId: customerId,
            });

            // Transform legacy response to modern JSON
            const customer = this.transformLegacyCustomer(soapResponse);

            // Add modern API features
            res.set('ETag', this.generateETag(customer));
            res.json(customer);
        } catch (error) {
            if (error.code === 'CUSTOMER_NOT_FOUND') {
                return res.status(404).json({
                    error: 'customer_not_found',
                    message: 'Customer not found',
                });
            }

            // Log legacy system errors but return modern error response
            this.logger.error('Legacy system error', error);
            res.status(500).json({
                error: 'internal_error',
                message: 'Service temporarily unavailable',
            });
        }
    }

    transformLegacyCustomer(legacyData) {
        // Transform legacy SOAP XML to modern JSON
        return {
            id: legacyData.CustomerId,
            name: {
                first: legacyData.FirstName,
                last: legacyData.LastName,
            },
            email: legacyData.EmailAddress,
            phone: legacyData.PhoneNumber,
            address: {
                street: legacyData.StreetAddress,
                city: legacyData.City,
                state: legacyData.State,
                zipCode: legacyData.ZipCode,
            },
            createdAt: new Date(legacyData.CreateDate).toISOString(),
            updatedAt: new Date(legacyData.LastUpdateDate).toISOString(),
        };
    }
}
