#### 4.6.2 Event-Driven API Implementation

```javascript
// Real-time event API
class EventStreamAPI {
    constructor() {
        this.app = express();
        this.eventBus = new EventBus();
        this.setupSSE();
        this.setupWebhooks();
    }

    setupSSE() {
        // Server-Sent Events for real-time updates
        this.app.get('/api/v1/events/stream', async (req, res) => {
            const userId = req.auth.sub;
            const eventTypes = req.query.types?.split(',') || ['all'];

            // Setup SSE connection
            res.writeHead(200, {
                'Content-Type': 'text/event-stream',
                'Cache-Control': 'no-cache',
                Connection: 'keep-alive',
                'Access-Control-Allow-Origin': '*',
            });

            // Send initial connection event
            res.write(
                `data: ${JSON.stringify({
                    type: 'connection_established',
                    timestamp: new Date().toISOString(),
                })}\n\n`
            );

            // Subscribe to user-specific events
            const subscription = this.eventBus.subscribe(`user.${userId}.*`, (event) => {
                if (eventTypes.includes('all') || eventTypes.includes(event.type)) {
                    res.write(`data: ${JSON.stringify(event)}\n\n`);
                }
            });

            // Cleanup on client disconnect
            req.on('close', () => {
                subscription.unsubscribe();
            });
        });
    }

    setupWebhooks() {
        // Webhook endpoint for external systems
        this.app.post('/api/v1/webhooks/:webhookId', async (req, res) => {
            const webhookId = req.params.webhookId;
            const event = req.body;

            try {
                // Validate webhook signature
                const isValid = await this.validateWebhookSignature(
                    req.headers['x-webhook-signature'],
                    req.body,
                    webhookId
                );

                if (!isValid) {
                    return res.status(401).json({ error: 'invalid_signature' });
                }

                // Process webhook event
                await this.processWebhookEvent(webhookId, event);

                res.status(200).json({ received: true });
            } catch (error) {
                this.logger.error('Webhook processing error', error);
                res.status(500).json({ error: 'processing_failed' });
            }
        });
    }

    async processWebhookEvent(webhookId, event) {
        // Transform external event to internal format
        const internalEvent = {
            id: generateEventId(),
            type: `webhook.${event.type}`,
            source: webhookId,
            timestamp: new Date().toISOString(),
            data: event.data,
        };

        // Publish to internal event bus
        await this.eventBus.publish(internalEvent);

        // Store event for audit trail
        await this.eventStore.store(internalEvent);
    }
}
