### 7.2 Pagination Patterns

```javascript
// Cursor-based pagination for large datasets
class PaginationHelper {
    static async paginate(query, options = {}) {
        const { limit = 25, cursor = null, sortField = 'id', sortDirection = 'asc' } = options;

        // Build query with cursor
        if (cursor) {
            const operator = sortDirection === 'asc' ? '$gt' : '$lt';
            query[sortField] = { [operator]: cursor };
        }

        // Fetch one extra item to check if there are more results
        const items = await this.model
            .find(query)
            .sort({ [sortField]: sortDirection === 'asc' ? 1 : -1 })
            .limit(limit + 1);

        const hasMore = items.length > limit;
        if (hasMore) {
            items.pop(); // Remove the extra item
        }

        const nextCursor = hasMore && items.length > 0 ? items[items.length - 1][sortField] : null;

        return {
            data: items,
            pagination: {
                hasMore,
                nextCursor,
                limit,
            },
        };
    }
}

// Usage example
app.get('/api/v1/users', async (req, res) => {
    const { limit, cursor } = req.query;

    const result = await PaginationHelper.paginate(
        { status: 'active' },
        { limit: parseInt(limit) || 25, cursor }
    );

    res.json(result);
});
```

