### 7.3 Caching Patterns

```javascript
// Multi-level caching strategy
class CacheManager {
    constructor() {
        this.redis = new Redis(process.env.REDIS_URL);
        this.memoryCache = new Map();
    }

    async get(key, options = {}) {
        const {
            ttl = 300, // 5 minutes default
            useMemoryCache = true,
            serialize = true,
        } = options;

        // Check memory cache first (fastest)
        if (useMemoryCache && this.memoryCache.has(key)) {
            const cached = this.memoryCache.get(key);
            if (cached.expiry > Date.now()) {
                return cached.data;
            } else {
                this.memoryCache.delete(key);
            }
        }

        // Check Redis cache (fast)
        const redisValue = await this.redis.get(key);
        if (redisValue) {
            const data = serialize ? JSON.parse(redisValue) : redisValue;

            // Store in memory cache for next time
            if (useMemoryCache) {
                this.memoryCache.set(key, {
                    data,
                    expiry: Date.now() + ttl * 1000,
                });
            }

            return data;
        }

        return null;
    }

    async set(key, value, options = {}) {
        const { ttl = 300, useMemoryCache = true, serialize = true } = options;

        const serializedValue = serialize ? JSON.stringify(value) : value;

        // Store in Redis
        await this.redis.setex(key, ttl, serializedValue);

        // Store in memory cache
        if (useMemoryCache) {
            this.memoryCache.set(key, {
                data: value,
                expiry: Date.now() + ttl * 1000,
            });
        }
    }
}

// Usage with HTTP caching headers
const cache = new CacheManager();

app.get('/api/v1/users/:userId', async (req, res) => {
    const userId = req.params.userId;
    const cacheKey = `user:${userId}`;

    // Check cache first
    let user = await cache.get(cacheKey);

    if (!user) {
        user = await User.findById(userId);
        if (user) {
            await cache.set(cacheKey, user, { ttl: 600 }); // 10 minutes
        }
    }

    if (!user) {
        return res.status(404).json({ error: 'User not found' });
    }

    // Set HTTP cache headers
    const etag = generateETag(user);
    res.set({
        ETag: etag,
        'Cache-Control': 'private, max-age=300', // 5 minutes
        'Last-Modified': user.updatedAt.toUTCString(),
    });

    // Check if client has current version
    if (req.headers['if-none-match'] === etag) {
        return res.status(304).end();
    }

    res.json(user);
});
```

