### 7.4 Rate Limiting Patterns

```javascript
// Advanced rate limiting with different strategies
class RateLimiter {
    constructor() {
        this.redis = new Redis(process.env.REDIS_URL);
    }

    // Token bucket algorithm
    async checkTokenBucket(key, capacity, refillRate, tokens = 1) {
        const now = Date.now();
        const bucketKey = `bucket:${key}`;

        const bucket = await this.redis.hmget(bucketKey, 'tokens', 'lastRefill');
        let currentTokens = parseFloat(bucket[0]) || capacity;
        let lastRefill = parseInt(bucket[1]) || now;

        // Refill tokens based on time passed
        const timePassed = (now - lastRefill) / 1000;
        const tokensToAdd = timePassed * refillRate;
        currentTokens = Math.min(capacity, currentTokens + tokensToAdd);

        if (currentTokens >= tokens) {
            currentTokens -= tokens;

            await this.redis.hmset(bucketKey, {
                tokens: currentTokens,
                lastRefill: now,
            });
            await this.redis.expire(bucketKey, 3600); // 1 hour expiry

            return {
                allowed: true,
                tokensRemaining: Math.floor(currentTokens),
                retryAfter: null,
            };
        } else {
            const retryAfter = Math.ceil((tokens - currentTokens) / refillRate);

            return {
                allowed: false,
                tokensRemaining: Math.floor(currentTokens),
                retryAfter,
            };
        }
    }

    // Sliding window rate limiting
    async checkSlidingWindow(key, limit, windowSizeMs) {
        const now = Date.now();
        const windowStart = now - windowSizeMs;
        const windowKey = `window:${key}`;

        // Remove old entries and count current requests
        await this.redis.zremrangebyscore(windowKey, '-inf', windowStart);
        const currentCount = await this.redis.zcard(windowKey);

        if (currentCount < limit) {
            // Add current request
            await this.redis.zadd(windowKey, now, `${now}-${Math.random()}`);
            await this.redis.expire(windowKey, Math.ceil(windowSizeMs / 1000));

            return {
                allowed: true,
                requestsRemaining: limit - currentCount - 1,
                resetTime: now + windowSizeMs,
            };
        } else {
            // Find when the oldest request will expire
            const oldestEntry = await this.redis.zrange(windowKey, 0, 0, 'WITHSCORES');
            const resetTime =
                oldestEntry.length > 0
                    ? parseInt(oldestEntry[1]) + windowSizeMs
                    : now + windowSizeMs;

            return {
                allowed: false,
                requestsRemaining: 0,
                resetTime,
            };
        }
    }
}

// Rate limiting middleware
function createRateLimit(options = {}) {
    const {
        strategy = 'sliding_window',
        limit = 100,
        windowMs = 60000, // 1 minute
        keyGenerator = (req) => req.ip,
        onLimitReached = null,
    } = options;

    const limiter = new RateLimiter();

    return async (req, res, next) => {
        const key = keyGenerator(req);
        let result;

        if (strategy === 'token_bucket') {
            result = await limiter.checkTokenBucket(key, limit, limit / (windowMs / 1000));
        } else {
            result = await limiter.checkSlidingWindow(key, limit, windowMs);
        }

        // Set rate limit headers
        res.set({
            'X-RateLimit-Limit': limit.toString(),
            'X-RateLimit-Remaining': (
                result.tokensRemaining ||
                result.requestsRemaining ||
                0
            ).toString(),
            'X-RateLimit-Reset': result.resetTime
                ? Math.ceil(result.resetTime / 1000).toString()
                : '',
        });

        if (!result.allowed) {
            if (onLimitReached) {
                onLimitReached(req, res);
            }

            if (result.retryAfter) {
                res.set('Retry-After', result.retryAfter.toString());
            }

            return res.status(429).json({
                error: 'rate_limit_exceeded',
                message: 'Too many requests',
                retryAfter: result.retryAfter,
            });
        }

        next();
    };
}

// Usage examples
app.use(
    '/api/v1/public',
    createRateLimit({
        limit: 100,
        windowMs: 60000,
        keyGenerator: (req) => req.ip,
    })
);

app.use(
    '/api/v1/users',
    createRateLimit({
        strategy: 'token_bucket',
        limit: 1000,
        windowMs: 3600000, // 1 hour
        keyGenerator: (req) => req.auth?.sub || req.ip,
    })
);
```

