```javascript
const APM = require('elastic-apm-node');

app.use((req, res, next) => {
    const span = APM.startSpan(`${req.method} ${req.path}`);
    res.on('finish', () => {
        span?.end();
    });
    next();
});
```

**Solutions**:

1. **Add caching**:

```javascript
// Cache expensive operations
const cache = new NodeCache({ stdTTL: 300 }); // 5 minutes

app.get('/api/v1/expensive-operation', async (req, res) => {
    const cacheKey = `expensive:${JSON.stringify(req.query)}`;

    let result = cache.get(cacheKey);
    if (!result) {
        result = await performExpensiveOperation(req.query);
        cache.set(cacheKey, result);
    }

    res.json(result);
});
```

2. **Optimize database queries**:

```javascript
// Use database indexes and query optimization
const users = await User.find({ status: 'active' })
    .select('id name email') // Only select needed fields
    .populate({
        path: 'profile',
        select: 'firstName lastName',
    })
    .lean() // Return plain objects instead of Mongoose documents
    .limit(100);
```

